import numpy as np
K=10
def fit_ncrda(X, y, e, lam, K=10):
    """Noise-corrected regularised QDA. Crowd label = gold w.p. 1-e else uniform."""
    n,p=X.shape
    pc=np.bincount(y,minlength=K)/n
    pg=np.maximum((pc-e/K)/(1-e),1e-3); pg/=pg.sum()
    a=(1-e)*pg/((1-e)*pg+e/K)            # fraction of crowd-class-k rows that are truly class k
    muM=X.mean(0); SM=X.T@X/n
    mu=np.zeros((K,p)); S=np.zeros((K,p,p))
    for k in range(K):
        A=X[y==k]; m=A.mean(0); s=A.T@A/len(A)
        mu[k]=(m-(1-a[k])*muM)/a[k]
        S[k]=(s-(1-a[k])*SM)/a[k]-np.outer(mu[k],mu[k])
    pooled=(S*pg[:,None,None]).sum(0)
    Sig=(1-lam)*S+lam*pooled
    # ensure PD
    for k in range(K):
        w,V=np.linalg.eigh(Sig[k]); w=np.maximum(w,1e-3*w.max()); Sig[k]=(V*w)@V.T
    return dict(pi=pg,mu=mu,Sig=Sig,e=e)
def logN(A, mu, C):
    L=np.linalg.cholesky(C); d=np.linalg.solve(L,(A-mu).T)
    return -0.5*(d**2).sum(0) - np.log(np.diag(L)).sum()
def scores(M, A):
    return np.stack([logN(A,M['mu'][k],M['Sig'][k]) for k in range(K)],1)+np.log(M['pi'])
if __name__=='__main__':
    import sys; sys.path.insert(0,'/tmp'); from harness import load
    X,y,Xd,yd=load()
    for e in [0.0,0.15,0.25,0.3,0.33]:
        row=[]
        for lam in [0.5,0.7,0.8,0.9,0.95,1.0]:
            M=fit_ncrda(X,y,e,lam); row.append((scores(M,Xd).argmax(1)==yd).mean())
        print('e',e,'lam 0.5..1.0:',np.round(row,3))
EOF
